      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Since some articles were written in Chinese and Japanese, no language restrictions were imposed. Irrelevant, duplicate and review studies were excluded.",
