      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "null",
      "quote": "null",
      "reason": "The text mentions 'lack of motor function evaluation' as an exclusion criterion but does not explicitly distinguish between exclusion because outcomes were not measured versus exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "publication bias was not observed in either active immunization (p = 0.131) or passive immunization studies (p = 0.272)",
      "reason": "The text specifies the groups used in synthesis (active immunization vs passive immunization) and links them to the intervention comparisons defined in the objectives (Text 3)."
    },
